-- Generated from PDF text extraction; source text is stored in nodes.content.
-- PostgreSQL schema: one row per source PDF, nodes stored as JSONB.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY, title TEXT NOT NULL, original_title TEXT, document_type TEXT NOT NULL, year_bs INTEGER NOT NULL, year_ad INTEGER NOT NULL, total_pages INTEGER NOT NULL, nodes JSONB NOT NULL, source_filename TEXT NOT NULL
);

INSERT INTO legal_documents (id,title,original_title,document_type,year_bs,year_ad,total_pages,nodes,source_filename) VALUES ($CODEx1f93f54b89$doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac$CODEx1f93f54b89$,$CODEx0c12f252d7$The Consumer Protection Act, 2075 (2018)$CODEx0c12f252d7$,NULL,$CODEx76f3b5a717$act$CODEx76f3b5a717$,2075,2018,34,$CODExb5b2a3640d$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "The Consumer Protection Act, 2075 (2018)\nDate of Authentication\n2075/6/2 (18 September 2018)\nAct Number 10 of the year 2075 (2018)\nAn Act Made to Provide for Amendment and Consolidation of Laws\nRelating to Consumer Protection\nPreamble:\nWhereas, it is expedient to make amendment to and consolidation of the legal\nprovisions relating to consumer protection in order to protect and promote constitutional\nrights of the consumers to obtain quality goods and services, to provide judicial remedy\nfor the enforcement of the rights obtained by the consumers, and provide compensation\nfor harm and injury likely to be caused to the consumers;\nNow, therefore, be it enacted by the Federal Parliament.", "children": []}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-1", "title": "Chapter-1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short Title and Commencement: (1) This Act may be cited as the “Consumer", "content": "Protection Act, 2075 (2018).\"\n(2) This Act shall commence immediately.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definition: Unless the subject or the context otherwise requires, in this Act,-", "content": "(a) \"Court\" means the Consumer Court referred to in Section 41.\n(b) \"Unfair trade and business\" means any activity referred to in Section\n16.\n(c) \"Production\" means the process of producing, preparing, refining,\nchanging, mixing, packaging or repackaging, assembling or\nlabeling, or any or all the processes to be adopted in this regard\n(d) \"Consumer\" means a person or institution that consumes or uses any\ngoods or services.\n(e) \"Consumer association\" means the institution established under the\nprevailing law with the objective of protecting and promoting the\nrights and welfare of the consumers.\n(f) \"Central Monitoring Committee\" means the Central Market\nMonitoring Committee referred to in Section 25.\n1\n(g) \"Sub-standard goods\" means consumer goods of any of the\nfollowing conditions:\n(1) Goods the quality of which falls short of the standards\ndetermined under Section 6 or in which the quantity of an\nessential ingredient has been lowered, or any other material\nhas been mixed.\n(2) Goods which are stale, rotten or stored or prepared in dirty\nor toxic conditions or in which any chemical, colour or\nflavour has been used, so that they become harmful to human\nhealth,\n(3) Goods which are fully or partly made of any diseased or\ndisease-generating animals or birds or harmful vegetation,\n(4) Goods which are produced, transported, hoarded, stored or\nsold without meeting the standard prescribed,\n(5) Goods which have no quality of consumable goods if it is\nprescribed, and as mentioned by the producer, if it is not\nprescribed,\n(6) Goods the quality of which falls short of the minimum\nnecessary standards or exceeds the maximum standards\nprescribed, if any, in this Act or in the rules framed under\nthis Act.\n(h) \"Prescribed\" or \"as prescribed\" means prescribed or as prescribed in\nthe rules framed under this Act.\n(i) \"Inspection Officer\" means the Inspection Officer appointed or\ndesignated pursuant to Section 32.\n(j) \"Council\" means the Consumer Protection Council to be formed\npursuant to sub-section (1) of Section 22.\n(k) \"Laboratory\" means the body established with the objective of\ntesting the purity, perfection or quality of the goods and recognized\nby the Government of Nepal.\n(l) \"Ministry\" means the Ministry of Industry, Commerce and Supply\nof the Government of Nepal.\n(m) \"Label\" means a tag, sign, picture or other descriptive thing written,\nprinted, lithographed, signed, embossed, included or displayed in\n2\nany other manner, in or on the goods or the container containing\nsuch goods.\n(m) \"Goods\" means the substance which the consumers consume or use\nor the materials made of the mixture of goods which do not inflict\nharm and injury or any kind of side effect to health, and this term\nalso includes the raw material, colour, fragrance or chemical to be\nused in the production of such goods.\n(n) \"Price of goods\" means the price the price labeled at the time of\nproduction, maximum retail price (M.R.P.), the price fixed in the\nimport declaration form or the price fixed at the source by the\nproducer.\n(o) \"Seller\" means the person, firm, company or institution that sells\nand distributes goods or services.\n(p) \"Department\" means the Commerce, Supplies and Consumer\nWelfare Protection Department.\n(q) \"Service\" means electricity, drinking water supply, telephone,\ninformation technology, health, education and consultation,\ntransport, drainage, banking or other services of similar nature, and\nthis term also includes legal, medical or engineering services.\n(r) \"Defective product\" means any goods or services that do not contain\nsuch minimum safety measures due to any of the following as are\nreasonably expected by the general people while using any product:\n(1) defective design, construction, refinement, mixture or\ninstallation,\n(2) defective packaging, protection or storage,\n(3) defective presentation,\n(4) lack of sufficient measure or precaution to control the\npotential risk or hazard as per the nature of the produced\ngoods or services,\n(5) product which is different or pirated or imitated from the\nproduct produced by the manufacturing company possessing\nthe intellectual property right.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-2", "title": "Chapter-2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "3", "title": "Rights of the consumer: (1) Every consumer shall have the right to obtain quality", "content": "goods and services.\n(2) Without prejudice to the generality of sub-section (1), for the\npurpose of protecting the rights, interests and concern of the consumers, every\nconsumer shall have the following rights:\n(a) right of easy access to goods or services,\n(b) right to choose quality goods or services at the fair\ncompetitive price,\n(c) right to be informed of the price, quantity, purity, quality etc.\nof the goods or services,\n(d) right to obtain information from the producer, importer or\nseller regarding the quantity, ingredient or percentage of the\nsubstances contained in the goods made of or produced with\nthe mixture of two or more than two substances,\n(e) right to be safe from the sale and distribution of the goods\nand services that inflict harm to the human body, life, health\nand property,\n(f) right to get appropriate legal action taken against the unfair\ntrade and business activities,\n(g) right to obtain compensation against harm and injury caused\nwith the use of goods or services,\n(h) right to receive remedy or hearing from the competent\nauthority or entity on the protection of the rights and interests\nof the consumers,\n(i) right to get consumer education.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Regulation of goods or services: (1) The Government of Nepal shall regulate the", "content": "supplies, price, quality, measurement, label, advertisement of the goods and\nservices regularly in order to protect the rights of the consumers.\n(2) The Ministry shall perform the following functions in conducting\nregulation pursuant to sub-section (1):\n(a) to implement the policy relating to quality, price\ndetermination and supply system of goods or services,\n(b) to prevent or control monopoly or unfair trade activities that\ncause or possibly cause adverse impact upon the rights and\n4\ninterests of the consumers, or to formulate and implement a\nplan of action in this regard,\n(c) to maintain fair market by continuously analyzing and\nreviewing the condition of demand and supply of the goods\nor services used within the country,\n(d) to make necessary provisions to prevent and control the price\ndetermined or increased in an undesired manner by the\nproducer, seller or distributor of the goods or services,\n(e) to facilitate the supply system through the institutions or\nprivate firms or companies having full or partial ownership\nof the Government of Nepal in order to ensure the supplies\nof the food and other goods for the consumers at a fair price\nand easy manner,\n(f) to fix the maximum quantity of the storage of the goods in\nany special circumstance, or at any particular place, for the\nperiod prescribed,\n(g) to receive foods from the producers at the prescribed price\nand sell them to the general people with determining certain\nquantity of such foods in case there is a shortage of any foods\nproduced within Nepal,\n(h) to make necessary provision to maintain uniformity in the\nprice in general, by managing wholesale or retail business,\n(i) to coordinate with the concerned agencies to prevent\nartificial shortage of any goods or services from occurring or\nto regularly distribute the goods in all places, for protecting\nthe rights of the consumers and regulating the supply system,\n(j) to regulate the sale and distribution system of goods, and\ncontrol the act of creating scarcity or black-marketing in an\ninappropriate manner or the unfair business activities.\n(3) The Government of Nepal may, in order to protect the rights of the\nconsumers, regulate the supply system and control the price and quality of the\ngoods and services, make necessary policy and institutional provisions from time\nto time.\n(4) The provision referred to in sub-section (3) shall have to be\nimplemented as prescribed.\n5", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Quality of goods and services: (1) In case the quality or standards of any", "content": "substance inherent in any goods have not been determined, the Government of\nNepal shall determine the standards or quality of such goods or services by\nfulfilling the process as prescribed.\n(2) The Government of Nepal shall have to publish the notice of the\nmatters of the standards or quality of any goods or service determined pursuant to\nsub-section (1) in the Nepal Gazette.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "To affix label: (1) A producer shall have to affix label on the goods produced by", "content": "him or her.\n(2) The following matters shall have to be mentioned in the label\npursuant to sub-section (1):\n(a) Name, address of the producer and registration number of the\nindustry,\n(b) Mixture, ingredient of mixture, quantity and weight of the\ngoods, in such goods as food, medicines and cosmetics,\n(c) In the case of the goods of which quality has been\ndetermined, the quality of such goods,\n(d) Mode of using the goods and side effect likely to occur due\nto the use of such goods,\n(e) In the case of the goods supposed to be used within a certain\ndeadline, such deadline,\n(f) Retail price, batch number and date of manufacture of the\ngoods,\n(g) If it is electronic, hardware, electrical or machinery or goods\nto be in use for a long time, guarantee or warranty and\nguarantee or warranty date of such goods, and other\nnecessary things in accordance with the law related to such\ngoods,\n(h) If any defect is seen in the condition referred to in clause (g),\nprovision to make reimbursement or to repair until certain\nperiod,\n(i) In the case of the goods that are inflammable, hazardous or\nlikely to break down easily, details relating to precaution to\nbe adopted for the safety of such goods,\n6\n(j) Maximum retail price to be incurred after including all types\nof taxes applicable for the goods,\n(k) If any process is supposed to be fulfilled prior to using any\ngoods, such process; and harm and injury likely to occur\nwhen it is used without fulfilling such process,\n(l) Use of awareness-oriented message, picture or sign on the\nlabel of the materials of the types of causing harm upon\nhuman health,\n(m) Other matters as prescribed.\n(3) The matters to be specified in the label pursuant to sub-section (2)\nshall have to be written in the Nepali or English language by the producer in the\ncase of the goods produced within Nepal and by the importer in the case of the\ngoods imported, in the way which can be understood by common people.\n(4) The goods on which label is not affixed pursuant to sub-section (3)\nshall not be allowed to be imported, sold and distributed in Nepal.\n(5) Notwithstanding anything contained elsewhere in this Section, it\nshall not be necessary to specify the matters set forth in this Section, while selling\nconsumable goods such as vegetables, fruits to be sold openly.\nProvided that the label shall have to be affixed on the imported vegetables\nand fruits.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-3", "title": "Chapter-3", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "7", "title": "Liability of producer: (1) While producing goods or services, the producer shall", "content": "have to fulfill the following liabilities, in addition to the liabilities to be fulfilled\nunder the prevailing laws:\n(a) to produce quality goods or services,\n(b) to determine the label of the goods,\n(c) to specify the matters referred to in Section 6 on the label,\n(d) not to produce defective product,\n(e) to collect and destroy the goods produced by him or her if it\nis informed that such goods remain in the market upon\nhaving been defectively produced,\n7\n(f) to provide reasonable compensation if any kind of damage is\ncaused to the consumer due to the manufacture of goods and\nservice,\n(g) not to make wrong or misleading advertisement or publicity\nof the goods or services,\n(h) to provide the consumer with information as to the quantity,\ningredients or percentage of the substances contained in the\ngoods made of or produced with the mixture of two or more\nthan two substances.\n(i) to fulfill such other conditions as prescribed by the law.\n(2) If the liability pursuant to sub-section (1) is not fulfilled or any\nfault, deficiency and defect occurs in the process of production, construction,\nrefinement, design, formula, preparation, import, packing, labeling, and harm and\ninjury is caused to anyone’s body, life, property after using such goods or services,\nthe producer of such goods or services shall be responsible for such harm and\ninjury and shall have the liability to provide compensation for the same.\nProvided that,\n(a) it must be the actual producer of the goods or services, the\nuse of which causes harm and injury,\n(b) direct cause must be established that harm and injury is\ncaused with the consumption or use of the goods or services\nas claimed for causing such harm and injury.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Liability of importer: (1) While importing goods, the importer shall have to", "content": "fulfill the following liabilities, in addition to the liabilities to be fulfilled under\nlaw:\n(a) to import without exceeding or making different from the\ncost price,\n(b) to provide details of the goods relating to the imported goods\nwhen so demanded by the concerned agency or official,\n(c) not to import the goods prohibited to be imported under the\nprevailing law,\n(d) to fulfill such other liabilities as prescribed.\n(2) Notwithstanding anything contained in sub-section (1), except for\nthe provision made otherwise as per the quality or nature of any goods, the goods\nshall be forbidden to be imported which are not supposed to or cannot be used\n8\nafter six months from the date of being imported or which cannot be used after the\nexpiry of such period.\n(3) If anyone imports the goods without specifying the matters to be\nspecified on the label, and if harm and injury is caused to anybody due to the use\nof such goods, the importer shall be responsible for such harm and injury and be\nliable to provide compensation for the same.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Liability of carrier: The carrier shall have to fulfill the following liabilities, in", "content": "addition to the liabilities to be fulfilled under law:\n(a) to transport within the determined time period as per the\nnature of the goods to be imported,\n(b) to prevent degradation in the quality of goods while\ntransporting,\n(c) to completely abide by the safety arrangement and the\nconditions to be abided by as prescribed, while transporting,\n(d) to provide the details of the goods when the concerned\nagency or official so demands,\n(e) to fulfill such other liabilities as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "Liability of hoarder: The hoarder who hoards the goods shall have to fulfill the", "content": "following liabilities in addition to the liabilities to be fulfilled under the prevailing\nlaw:\n(a) to exercise care as per the nature of the goods while hoarding\nsuch goods,\n(b) to hoard upon adopting safety measures as prescribed so as\nto prevent degradation in the quality as per the type or nature\nof the goods, and not to do any act that may cause\ndegradation in the quality of goods,\n(c) not to change or replace the label or details specified by the\nproducer,\n(d) to provide the details of the goods related to the hoarding of\nthe goods when the concerned agency or the official so\ndemands,\n(e) to adopt safety measures as prescribed,\n(f) to fulfill other liabilities as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Liability of seller: The seller who sells the goods shall have to fulfill the following", "content": "liabilities, in addition to the liabilities to be fulfilled under the law:\n9\n(a) to sell the goods to the consumers without discrimination,\n(b) to safely keep and safely sell the goods as per the type or\nnature by preventing degradation,\n(c) to keep price list of the goods so that it is clearly seen and\nunderstood by general people,\n(d) to provide storage or details of the goods remained with him\nor her when the concerned agency or official so demands,\n(e) to abide by the provision of guarantee or warranty, if any, in\nthe goods,\n(f) to sell the goods to the customers on a first-come-first-served\nbasis,\n(g) to give the bill or receipt on selling the goods,\n(h) to fulfill other liabilities as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "Liability of service provider: The service provider providing service to the", "content": "consumer shall have to fulfill the following liabilities, in addition to the liabilities\nto be fulfilled under the law:\n(a) to provide the consumer with the service without\ndiscrimination,\n(b) to keep nature of the service to be provided and the list of the\nprice to be paid by the consumers for such service received,\nat the place visible to everyone, so that it is clearly\nunderstood by the general people,\n(c) to provide the details and documents related to the service to\nbe provided when the concerned agency or official so\ndemands,\n(d) to provide the service to the customer on a first-come-first-\nserved basis,\n(e) to give the bill or receipt after receiving the amount for the\nservice provided to the consumer,\n(f) to fulfill such other liabilities as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "To determine level of market: For the purpose of protecting the rights of", "content": "consumers, managing the market in accordance with the market rule and making\nmarket fair and transparent, the levels of market involved in taking the prescribed\ngoods or services from the producer or importer to the final consumer shall be as\nprescribed.\n10", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "To return goods: (1) If anyone wishes to return, being dissatisfied with, any goods", "content": "purchased from the seller, he or she may return it to the seller within seven days\nor take other similar goods equal to that price or the payment of the amount which\nwas paid while purchasing such goods.\n(2) While returning the goods pursuant to sub-section (1), the seller shall\nnot be allowed to make deduction in the price or take any kind of additional charge.\n(3) While returning the goods pursuant to sub-section (1), the bill or receipt\ngiven by the seller at the time of purchasing such goods shall have to be produced.\n(4) Notwithstanding anything contained in sub-section (1), no goods may\nbe returned or taken as replacement in the following circumstances:\n(a) if the quality or quantity of such goods is altered by the\npurchaser after the purchase,\n(b) in the case of the goods of such nature that they must be used\nwithin the certain deadline, such deadline has already\nexpired,\n(c) in the case of the goods of such nature as being rotten,\noverripe, such as milk, fruits, fish, meat, in case they are not\nconsumed instantly,\n(d) if the purchased goods are already used,\n(e) if the seal is broken off in the case of sealed goods.\n(5) Notwithstanding anything contained elsewhere in this Section, in the\ncase of sealed goods, such goods may be returned within fifteen days, in the\nunbroken condition of the seal, or other similar goods equal to the same price may\nbe taken instead of such goods.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "To keep bill or invoice: (1) The importer, carrier, hoarder and seller shall have to", "content": "keep with them the producer or purchase bill or invoice of the goods or services\npurchased for the purpose of sale.\n(2) The bill or invoice shall have to be shown at the time when the\nconcerned official so demands.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-4", "title": "Chapter-4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "16", "title": "Not to conduct unfair trade and business activities: (1) No one shall conduct or", "content": "cause to conduct unfair trade and business activities.\n11\n(2) For the purpose of sub-section (1), if any of the following activities is\nconducted, an unfair trade and business activity shall be deemed to have been\ntaken place:\n(a) selling or providing the goods or services by lying,\nconcealing, hiding or misleading the actual quality, quantity,\nprice, measurement, format or composition etc. of such\ngoods or services,\n(b) releasing false or misleading advertisement, or selling the\ngoods by making misleading advertisement,\n(c) doing any of the following acts through oral, written or visual\nmeans in the case of goods or services:\n(1) selling sub-standard goods by showing standard,\nquality, quantity, class, composition, design as if\nhaving specialty or quality,\n(2) selling re-produced or old goods showing or\nmisrepresenting that they are new one,\n(3) advertising or notifying and disseminating, in false\nand misleading manner, while selling the goods or\nservices even when no benefit is obtained as declared,\n(4) claiming, guaranteeing or selling any goods through\nconsumption or use of such goods without factual\nground.\n(d) determining price in a manner to shift burden upon the\nconsumer price on the ground different than the ground of\nactual cost of any goods or services, or fixing the price by\nincluding the cost of any contest, lottery, occasion, or selling\nat such price,\n(e) determining price by including the price or cost of other\ngoods to be obtained as donation, gift or without charge upon\nthe price of any goods or service, or selling such goods or\nservice at such price,\n(f) producing, mixing up or supplying or transporting or\nhoarding or selling the goods so as to become less or more\nthan the quality or standard in any goods or service, or to\n12\ninflict harm and injury upon the consumer from the use of\nsuch goods or service,\n(g) creating artificial shortage of, hoarding or selling, any goods,\n(h) selling the goods by including the price of goods destroyed\nby defective product or the price of goods contracted in the\ncourse of business transaction in the cost price of other\ngoods,\n(i) producing or importing fake goods or selling such goods to\ndisplace any goods,\n(j) refusing to issue bill or invoice of the sold goods or service,\nor not issuing bill or invoice, or demanding additional\namount while issuing bill, invoice,\n(k) using poison or any chemical so as to inflict harm and injury\nupon the consumer while using any goods, or selling the\ngoods so used,\n(l) selling the already expired goods by affixing new label on\nsuch goods which is not consumable or is not supposed to be\nused,\n(m) importing, producing or selling sub-standard goods which\ncannot be used,\n(n) providing service without specifying the price, quality of\nservice, venue and time to provide service by a professional\nservice provider,\n(o) selling so as to become contrary to sub-section (1) of Section\n17 in collusion with the producer, importer, carrier, hoarder\nor seller or such person and other person, organization and\ninstitution,\n(p) selling or providing by setting up levels or series more than\nthe business level prescribed while selling or providing any\ngoods or services,\n(q) selling without fulfilling the structure, measurement or\nstandard if any, prescribed for selling or providing any goods\nor service.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "Not to cause adverse impact on demand, supply or price: (1) No one shall sell,", "content": "distribute or transport or hinder the sale and distribution of any goods by taking\n13\nprofit higher than that prescribed and over the cost invested in the production,\nimport, transport, hoarding or sale and distribution of that goods.\n(2) No one shall cause adverse impact on the demand, supply or price\nof any goods or service by doing any of the following acts, in association with any\nperson, institution or anyone else:\n(a) determining quota of the raw materials required for the\nmanufacture of any goods, or reducing the production of any\ngoods or doing any other such work,\n(b) creating artificial shortage by hoarding any goods or service\nor by any other manner,\n(c) selling the goods or service at the determined time or place\nonly or doing other acts of similar nature.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "Other act not to be done regarding goods or service: No one shall do or cause", "content": "to be done any of the following acts, regarding any goods or services:\n(a) producing, selling or importing sub-standard goods\nknowingly,\n(b) selling any goods or services by lying or deceiving that the\ngoods or services are other goods or services and stating high\nstandard goods for low standard goods or services,\n(c) producing or selling the goods or service that cause adverse\nimpact upon the health of consumer,\n(d) affecting the price and supply system by creating shortage of\nthe goods by accompanying with businesspersons or business\ngroups in order to manufacture, import or sell various goods\nof the same nature,\n(e) operating service by adopting a circle system, quota system,\nrotational system, trip system or token system, in cooperation\nwith more than one business persons or business groups that\nprovide any service of the same nature,\n(f) making a provision requiring to purchase other goods too,\nwhile purchasing any goods.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-5", "title": "Chapter-5", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "19", "title": "List of essential food and other goods and service: (1) The Government of Nepal", "content": "shall determine the list of essential food and other goods or services by a\nnotification in the Nepal Gazette from time to time.\n(2) The maximum price of essential food and other goods or services\nshall also have to be fixed in the list pursuant to sub-section (1).\n(3) While selling the goods or service pursuant to sub-section (1), the\nseller shall not sell, or cause to be sold, the same in a price higher than that referred\nto in sub-section (2).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "20", "title": "To keep price list and registration certificate: (1) Price list shall have to be kept", "content": "by clearly specifying the factory price of each of the goods by the producer,\nwholesale or retail price of goods to be sold and distributed by the seller, and price\nof the service to be provided by the service provider.\n(2) If it is an industry to produce the goods, the industry registration\ncertificate, and in the case of business, business registration, license shall have to\nbe displayed at the place of sale in a way visible to the general people.\n(3) The Government of Nepal may, by a notification in the Nepal\nGazette, establish a price information center as prescribed.\n(4) The producer and wholesaler or retailer located in the district\nconcerned shall have to provide the factory price and the wholesale or retail price\nrespectively to the price information center established pursuant to sub-section\n(3).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "21", "title": "Provision to determine standard of price of goods or service: (1) The agency", "content": "as prescribed shall prepare the standards relating to determination of price of\ngoods or services as prescribed.\n(2) While preparing standards relating to price determination pursuant\nto sub-section (1), profit amount to be taken by the seller also shall have to be\naccepted as basis in such a way that production cost of the goods, transport\nexpenses, custom, tax, charge paid by the importer pursuant to law shall not be\nmore than the percentage fixed while selling.\n(3) While preparing standards relating to the determination of price of\nany service, if the agency prescribed pursuant to sub-section (1) has assigned\nanybody or authority in accordance with the law regulating or managing the\nconduct and functions of the person who provides such a service, the standards\nshall have to be prepared as per the standards determined by such a body or\nauthority.\n15\n(4) While preparing standards, in case the standards are not determined\neven after the body or authority is assigned pursuant to sub-section (3), such a\nbody or authority shall have to be consulted with.\n(5) While preparing standards relating to the determination of price\npursuant to sub-section (1) or (3), the standards may be determined differently to\nmake the maximum price, be taken for such goods or services provided, on the\nbasis of the geographical region, nature of the services and particular place.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-6", "title": "Chapter-6", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "22", "title": "Formation of Consumers Protection Council: (1) There shall be formed a", "content": "Consumer Protection Council in order to make policy on the matters of protecting\nand implementing the rights of consumers and performing other functions under\nthis Act.\n(2) The Council referred to in sub-section (1) shall consist of the\nfollowing Chairperson and Members:\n(a) Minister for Industry, Commerce and Supplies - Chairperson\n(b) Secretary, Ministry of Industry, Commerce\nand Supplies -Member\n(c) Secretary, Ministry of Agriculture and\nLivestock Development -Member\n(d) Secretary, Ministry of Land Management,\nCooperative and Poverty Alleviation -Member\n(e) Secretary, Ministry of Finance -Member\n(f) Secretary, Ministry of Home Affairs -Member\n(g) Secretary, Ministry of Law, Justice and\nParliamentary Affairs -Member\n(h) Secretary, Ministry of Health and Population -Member\n(i) Chairperson, Federation of Nepalese Chambers\nof Commerce and Industry -Member\n(j) Chairperson, Nepal Chamber of Commerce -Member\n(k) Chairperson, Confederation of Nepal Industries -Member\n16\n(l) Chairperson, Federation of Nepal National\nIndustries and Entrepreneurs -Member\n(m) Two persons including one woman\nnominated by the Ministry from among\nthe persons having experience of at least\nfive years in the body or institution related\nto the rights and welfare of the consumers -Member\n(n) Director General, the Department -Member-Secretary\n(3) The term of the Members nominated pursuant to clause (m) of sub-\nsection (2) shall be of two years, and they may be nominated again for another\nterm.\n(4) Notwithstanding anything contained in sub-section (3), the Ministry\nmay remove such a Member from the post at any time if any act is done contrary\nto the rights and interests of the consumers or act is done in such a way that it\nbecomes contrary to the functions, duties and powers of the Council.\n(5) Before removing from the post pursuant to sub-section (4), he or she\nshall have to be given a reasonable opportunity to submit clarification.\n(6) The Chairperson and Members of the Council shall be entitled to the\nmeeting allowance facility as prescribed by the Government of Nepal.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "Meeting of Council: (1) The meeting of the Council shall be convened at the date,", "content": "time and place fixed by the Chairperson.\n(2) The meeting of the Council shall be convened at least twice a year,\nand the interval between the two meetings shall not be more than six months.\n(3) If more than fifty percent members of the total members of the\nCouncil are present, it shall be deemed to constitute a quorum for the meeting of\nthe Council.\n(4) The Chairperson of the Council shall preside over the meeting, and\nin his or her absence, the Member selected from among the Members shall preside\nover the meeting.\n(5) Experts and scientists of different sectors, communities may be\ninvited to the meeting as necessary.\n(6) The decision of the Council shall be authenticated by the Member-\nSecretary of the Council.\n(7) Other procedures relating to the meeting of the Council shall be as\ndetermined by the Council itself.\n17\n(8) The Department shall perform the functions as the Secretariat of the\nCouncil.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "24", "title": "Functions, duties and powers of the Council: The functions, duties and powers", "content": "of the Council shall be as follows:\n(a) to submit to the Government of Nepal by determining\npolicies on the matters regarding the protection and\nenforcement of the rights of the consumers, supply system\nand the determination of price and quality of goods and\nservices,\n(b) to provide necessary recommendation to the Government of\nNepal regarding the amendment, improvement in the existing\npolicies or new policies which are to be made regarding the\nprotection of the rights of consumers,\n(c) to disseminate and cause to be disseminated information\nrelating to the rights and welfare of the consumers to get the\nconsumers informed regarding the goods and services,\n(d) to inform or get the consumers informed regarding the price,\nquality, quantity, purity and unfair trade activities of the\ngoods or services,\n(e) to make necessary policy arrangements for including the\nconsumer education in the curriculum from secondary level\nup to the university level,\n(f) to draft necessary policies to cooperate with national and\ninternational organizations or institutions related to the\nrights of consumers,\n(g) to give directive to the Provincial Government or Local\nLevel to protect and promote the rights of the consumers as\nnecessary,\n(h) to perform such other functions as prescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-7", "title": "Chapter-7", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "25", "title": "Central Market Monitoring Committee: (1) A Central Market Monitoring", "content": "Committee shall be formed for the protection of the rights and interests of the\nconsumers or for making coordination among the bodies involved in the\n18\nmonitoring or inspection of the supply system, price, quality and purity of the\ngoods or services.\n(2) The Central Market Monitoring Committee referred to in sub-section\n(1) shall consist of the following Members:\n(a) Secretary, Ministry of Industry, Commerce\nand Supplies -Coordinator\n(b) Joint-secretary, Ministry of Industry,\nCommerce and Supplies (responsible\nthe supplies) -Member\n(c) Joint-secretary, Ministry of Home Affairs -Member\n(d) Secretary, Ministry of Agriculture and\nLivestock Development -Member\n(e) Secretary, Ministry of Land Management,\nCooperative and Poverty Alleviation -Member\n(f) Director General, Department of Food\nTechnology and Quality Control -Member\n(g) Director General, Nepal Bureau of Standards -Member\n(h) Director General, Department of Drug\nManagement -Member\n(i) Director General, Department -Member-Secretary\n(3) The procedures relating to the meeting of the Central Market\nMonitoring Committee shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Function, duties and powers of Central Market Monitoring Committee: The", "content": "functions, duties and powers of the Central Market Monitoring Committee shall\nbe as follows:\n(a) to take necessary initiative to make the goods or services\neasily available, by identifying their shortage seen in the\nmarket,\n(b) to monitor and supervise regarding the supply system, price,\nweight, quality, purity etc. of the goods or services in the\nmarket,\n(c) to make recommendation of the procedures of operation of\nmarket monitoring, monitoring team and consumers\norganizations and institutions,\n19\n(d) to maintain coordination in the functions of the Market\nMonitoring Team and Local Monitoring Committee,\n(e) to give necessary directives to the bodies that protect the\nrights and interests of the consumers and law enforcement\nbodies in order to make market monitoring effective,\n(f) to set up the Consumers Information Center,\n(g) to form committees or sub-committees as necessary,\n(h) to perform such other functions as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "27", "title": "Provincial Market Monitoring Committee: (1) The Provincial Government", "content": "may, in order to make necessary arrangements for protection of the rights and\nwelfare of the consumers, form a Provincial Market Monitoring Committee by a\nnotification in the Provincial Gazette, for carrying out inspection and monitoring\non the matters relating to the supply system, price, quality, purity of the goods or\nservices.\n(2) The Provincial Market Monitoring Committee referred to in sub-\nsection (1) may form monitoring teams or sub-committees as necessary.\n(3) The functions, duties and powers of the Provincial Market\nMonitoring Committee referred to in sub-section (1) shall be as prescribed.\n(4) Other provisions relating to the functions of the Provincial Market\nMonitoring Committee referred to in sub-section (1) shall be in accordance with\nthe rules framed by the Provincial Government.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "Local Market Monitoring Committee: (1) The Rural Municipality or", "content": "Municipality may, for the protection of the rights of consumers under this Act,\nform a Local Market Monitoring Committee for carrying out field inspection and\nmonitoring of the market on the matters relating to the supply system, price,\nquality, purity of the goods or services.\n(2) The Committee referred to in sub-section (1) shall also consist of\nthe bodies and consumers under the Local Level in necessary numbers.\n(3) The functions, duties, powers, work procedures and other necessary\nmatters of Local Market Monitoring Committee to be formed pursuant to sub-\nsection (1) shall be as prescribed.\n(4) The Local Market Monitoring Committee to be formed pursuant to\nsub-section (1) may form market monitoring teams or sub-committees as\nnecessary.\n20", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "29", "title": "To form Market Monitoring Team: (1) In order to monitor and supervise", "content": "regularly as to whether any unfair business activity has taken place pursuant to\nSection 16, price list is kept or not pursuant to Section 20, and regarding the\nquality, quantity or price of goods or services, Market Monitoring Team or\nSubject-wise Monitoring Team or Joint Monitoring Team consisting of the expert\nof the related sector as well as Inspection Officer may be formed as prescribed.\n(2) The Market Monitoring Team referred to in sub-section (1) may get\ninformation about or enquire into the quality, quantity, price determination of any\ngoods or services.\n(3) The Market Monitoring Team referred to in sub-section (1) may,\nwhile getting information or making inquiry pursuant to sub-section (2), demand\nnecessary document and evidence, and it shall be the duty of the producer or seller\nconcerned to submit such document or evidence.\n(4) The Market Monitoring Team referred to in sub-section (1) may\nexercise all the powers conferred to the Inspection Officer under this Act.\n(5) The Market Monitoring Team referred to in sub-section (1) shall,\nwhile making monitoring and inspection of the market, use the market monitoring\nand inspection form as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "30", "title": "To make inquiry or inspection: (1) If there is reasonable ground to believe that", "content": "any person is doing unfair trade or business activity, doing the act of affecting the\nprice or supply system by maintaining monopoly or any other manner in the\nmarket, or producing or selling and distributing sub-standard goods, or doing any\nact contrary to this Act or the rule framed under this Act, or if information is\nreceived regarding such matters through any means of communication or any\ncomplaint or through anyone that carries out surveillance, the Ministry or\nDepartment may immediately inquire into or inspect that matter or cause such\ninquiry or inspection to be made.\n(2) Inspection or monitoring shall be carried out accordingly if the\nprevailing law provides for monitoring and inspection, with respect to the\ninspection or inquiry pursuant to sub-section (1), and in other circumstances, the\nMinistry may form immediately an inspection or inquiry committee or designate\nany committee formed under this Act or the Inspection Officer to that effect.\n(3) Any producer, dealer, agent, seller, person or institution found\nguilty from the inquiry or inspection pursuant to sub-section (1) shall be liable to\naction under this Act or the prevailing law.\n21\n(4) If upon inspection or inquiry, the committee or the Inspection Officer\ndesignated pursuant to sub-section (2) does not find that such an act falls under\nthis Act, the committee or the officer shall send the matter, along with the inquiry\nor inspection file, to the concerned body for necessary action; and such a body\nshall also give information about the action taken in that respect to such a\ncommittee or officer.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Power to carry out casual inspection: (1) The Department may carry out casual", "content": "inspection for the protection of the rights, interests of the consumers.\n(2) Other provisions relating to casual inspection shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "Power to appoint or designate Inspection Officer: (1) The Department may, in", "content": "order to carry out monitoring of availability of the quality goods or services at\nappropriate price for consumers by making market and supply system effective,\nappoint Inspection Officer or designate any officer employee of the Government\nof Nepal, Provincial Government or Local Level to act as Inspection Officer as\nprescribed.\n(2) The qualification of the Inspection Officer appointed or designated\npursuant to sub-section (1) shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "33", "title": "Functions, duties and powers of Inspection Officer: (1) If there is reasonable", "content": "ground to believe that the unsafe goods having adverse effect or sub-standard\ngoods are being produced or sold, or services have been provided, or any acts are\nbeing done contrary to this Act and the rules framed under this Act, the Inspection\nOfficer may, by entering into such a place at any time as necessary, inspect, inquire\nor search, arrest the person who commits such act and hold such a person in\ndetention for seven days with the permission of the case trying authority.\n(2) In the course of inspection, inquiry or search pursuant to sub-section\n(1), necessary description, information or statement may be taken from the\nproducer, importer, carrier, hoarder, seller, service provider or other related\nperson.\n(3) While carrying out inspection, investigation or search pursuant to sub-\nsection (2), if it seems unsafe, affected goods or goods having no quality are being\nproduced or sold and distributed, or service provided or activities are contrary to\nthis Act and the rules framed under this Act, the Inspection Officer may impose\nrestriction on producing or selling and distribution of such goods or providing\nservices for prescribed period by taking samples of such goods as prescribed.\n22\n(4) A testing list of the goods or services shall have to be prepared as\nprescribed for the purpose of carrying out market inspection or inquiry pursuant\nto sub-section (1).\n(5) If it is not found to be in accordance with the testing list pursuant to\nsub-section (4), the Inspection Officer may immediately impose the fine referred\nto in Section 39 with restriction on the sale and distribution of such goods.\n(6) The report relating to the functions carried out by the Inspection\nOfficer pursuant to sub-section (2) shall have to be submitted to the Department\nwithin seven days.\n(7) If a fine is imposed pursuant to sub-section (5) in the report pursuant\nto Sub-section (6), report shall have to be prepared by specifying such details as\nwell.\n(8) If it seems appropriate to give any order immediately to the producer\nor seller in course of inspection or inquiry, the Inspection Officer may give such\nan order or do such other act as appropriate.\n(9) The procedures to be adopted by the Inspection Officer while\ncarrying out inspection, inquiry or search shall be as prescribed.\n(10) The Inspection Officer may, while carrying out inspection, inquiry\nor search, if it seems that any legal action is required to be taken against any\nproducer, seller, send it to the Department by mentioning such details in the report\nas well, or to other bodies concerned with the reason if needed.\n(11) The provisions relating to other functions, duties and powers of the\nInspection Officer and the implementation of the report furnished by the\nInspection Officer shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "34", "title": "Testing of goods: (1) The Inspection Officer shall forward, immediately the", "content": "samples of goods taken for testing pursuant to sub-section (3) of Section 33 to the\nlaboratory of the Government of Nepal or the laboratory accredited by the\nGovernment of Nepal, as prescribed if the goods are of the nature of being instantly\nrotten, overripe, and within twenty-four hours from the date of samples taken if\nthey are other goods.\n(2) The Inspection Officer shall, while forwarding samples to the\nlaboratory pursuant to sub-section (1), have to forward them by giving symbol\nnumbers to them.\n23\n(3) If a false result is given or negligence is found to have been made\nwhile testing the goods in the laboratory pursuant to sub-section (1), departmental\naction shall be taken against such an employee.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "35", "title": "To confiscate or destroy sub-standard goods: (1) If the goods are not found to", "content": "have the quality as prescribed while testing the samples of such goods forwarded\nto the laboratory for testing pursuant to Section 34, such goods shall be confiscated\nand shall, as required, be destroyed as prescribed.\n(2) When the goods are confiscated and destroyed pursuant to sub-\nsection (1), the producer, importer or seller shall have to bear the expenses for\nconfiscating or destroying such goods.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "36", "title": "To make complaint: (1) If any goods or service provider performs any act against", "content": "the consumer interest or contrary to this Act or any rule framed under this Act,\nany person who gets information of such matters may make a complaint in writing\nor orally or even through electronic means to the Central Market Monitoring\nCommittee, Department or Inspection Officer, along with the information or proof\nand evidence under his or her custody.\n(2) If the person who makes a complaint pursuant to sub-section (1)\nwishes to keep his or her name confidential, the name of such a person shall have\nto be kept confidential.\n(3) Other provisions relating to the complaint shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "37", "title": "Action against person leaking information: (1) Departmental action shall be", "content": "taken against a public servant, who leaks the information of casual inspection or\nthe monitoring to be carried out regularly pursuant to Section 31, before such\ninspection or monitoring takes place.\n(2) If information is leaked by a consumers’ organization or institution\nof consumers or other person involved in the act referred to in sub-section (1), the\nDirector General of the Department shall impose a fine on such person,\nrepresentative or institution in accordance with the claimed amount as revealed\nand from fifty thousand rupees up to one hundred thousand rupees if the claimed\namount in not set out, and such an organization or institution shall be included in\nthe black list for a period not exceeding three years.\n24", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-8", "title": "Chapter-8", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "38", "title": "Offences deemed to have been committed: If anyone does, or causes to be done,", "content": "any of the following acts, he or she shall be deemed to have committed the offence:\n(a) failure to make the labeling pursuant to Section 6 or\nmentioning false matters in the label,\n(b) failure of the producer, importer, carrier, hoarder, seller or\nservice provider to fulfill his or her liabilities or doing any\nact to breach such liabilities under Sections 7, 8, 9, 10, 11\nand 12 respectively,\n(c) failure of the seller to withdraw the goods within the deadline\nprescribed or failure to give the goods equal to such price as\nreplacement pursuant to Section 14,\n(d) failure to keep the bills, invoices pursuant to Section 15,\n(e) doing, or causing to be done, the unfair trade activity\npursuant to clause (a), (g), (j) or (l) of sub-section (2) of\nSection 16,\n(f) doing, or causing to be done, the unfair trade activity\npursuant to clauses (b), (c), (d), (e), (f), (h), (i), (k), (m), (o)\nand (p) of sub-section (2) of Section 16,\n(g) inflicting, or causing to be inflicted, adverse impact on\ndemand, supplies or price pursuant to clause (a) of sub-\nsection (1) or sub-section (2) of Section 17,\n(h) doing, or causing to be done, any act referred to in clause (b)\nor (c) of sub-section (2) of Section 17,\n(i) doing, or causing to be done, any act contrary to Section 18,\n(j) selling, or causing to be sold, at the price higher than that\nfixed by the Government of Nepal, contrary to sub-section\n(3) of Section 19,\n(k) failure to do, or causing not to be done, any act referred to\nin sub-section (1) or (2) of Section 20,\n(l) to sell or distribute goods or services contrary to the\nstandards determined under sub-section (1) of Section 21,\n25\n(m) not to render assistance in the course of investigation,\ninspection or monitoring under this Act pursuant to sub-\nsection (2) of Section 54.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "39", "title": "To impose fine instantly: (1) Notwithstanding anything contained in Section 38,", "content": "if from the instantly received evidence, the producer, carrier, hoarder, importer,\nseller of goods or service provider is found to have committed any offence, in the\ncourse of market monitoring, inspection, inquiry, the Inspection Officer may\nimpose the fine as follows:\n(a) From five thousand to twenty thousand rupees if the offence\nreferred to in clause (d) of Section 38 is committed, or caused\nto be committed,\n(b) From two hundred thousand to three hundred thousand\nrupees if the offence referred to in clause (e) of Section 38 is\ncommitted, or caused to be committed,\n(c) From fifty thousand rupees to one hundred thousand rupees\nif the offence referred to in clause (h) of Section 38 is\ncommitted or caused to be committed,\n(d) From fifty thousand to one hundred thousand rupees if the\noffence referred to in clause (k) of Section 38 is committed,\nor caused to be committed,\n(e) Up to twenty thousand rupees if the offence referred to in\nclause (m) of Section 38 is committed, or caused to be\ncommitted.\n(2) If the offence referred to in sub-section (1) is committed frequently,\ndouble fine shall be imposed for commission of the offence each time.\n(3) The Inspection Officer shall have to inform the Department within three\ndays by revealing all the details including the cause to impose the fine instantly\nand the amount charged thereof.\n(4) The Inspection Officer may take the following actions against the\nproducer, carrier, hoarder, importer or seller of such goods who does not pay or\nsubmit such fine within seven days from the date of the decision made to fine\ninstantly pursuant to sub-section (1):\n(a) keeping such goods sealed until the fine is paid,\n(b) withholding such other goods as well as to be produced,\ntransported, hoarded, imported or sold by the producer,\n26\ncarrier, hoarder, importer or seller of such goods until the\nfine is paid.\n(5) If one is not satisfied with any act of the Inspection Officer under this\nSection, an application may be made to the Director General of the Department\nwithin seven days for the review of the matter.\n(6) The Director General of the Department shall have to make a decision\nin this regard within twenty-one days after examining whatever or whoever is to\nbe examined upon the application made against the decision by the Inspection\nOfficer pursuant to sub-section (5).\n(7) While making an application for the review, fifty percent of the fine\nimposed by the Inspection Officer shall have to be submitted as a cash deposit.\n(8) The decision made by the Director General upon the application made\nfor the review shall be final.\n(9) Other procedures to be adopted regarding the instant imposition of fine\nby the Inspection Officer shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "40", "title": "Punishment: (1) If any one commits, or causes to be committed, any of the", "content": "following acts which is deemed to be an offence under this Act, the Director\nGeneral of the Department may, according to the gravity of the offence, punish as\nfollows:\n(a) with imprisonment from three months to six months or fine\nup to fifty thousand rupees or both penalties if the offence\nreferred to in clauses (a) and (c) of Section 38 is committed,\nor caused to be committed,\n(b) with imprisonment from three months to one year or fine\nfrom one hundred thousand rupees to three hundred thousand\nrupees or both penalties if the offence referred to in clause\n(i) of Section 38 is committed,\n(c) with imprisonment from three months to six months or fine\nfrom fifty thousand rupees to one hundred thousand rupees\nor both penalties if the offence referred to in clauses (j) and\n(l) of Section 38 is committed.\n(2) A party who is not satisfied with the decision made by the Director\nGeneral of the Department under sub-section (1) may appeal to the concerned\nDistrict Court within thirty-five days.\n(3) For the following offences, punishment shall be as follows:\n27\n(a) with imprisonment from two years to three years or fine from\nthree hundred thousand to five hundred thousand rupees or\nboth penalties for one who commits, or causes to be\ncommitted, the offence referred to in clause (b) of Section\n38,\n(b) with imprisonment from two years to five years or fine from\nfour hundred thousand to six hundred thousand rupees or\nboth penalties for one who commits, or causes to be\ncommitted, the offence referred to in clause (f) of Section 38,\n(c) with imprisonment from two years to three years or fine from\nthree hundred thousand to five hundred thousand rupees or\nboth penalties for one who commits, or causes to be\ncommitted, the offence referred to in clause (g) of Section\n38.\n(4) A person who commits, or causes to be committed, any other act\ncontrary to this Act or the rules framed under this Act, Except for the acts under\nsub-section (1), shall be punished with imprisonment for a term not exceeding two\nyears or fine up to three hundred thousand rupees or both.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-9", "title": "Chapter-9", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "41", "title": "Constitution of Consumer Court: (1) The Government of Nepal may, in order to", "content": "try and settle the cases other than the cases to be prosecuted pursuant to sub-\nsection (1) of Section 40 under this Act, constitute a Consumer Court as per\nnecessity, by a notification in the Nepal Gazette.\n(2) The venue and jurisdiction of the Consumer Court to be formed\npursuant to sub-section (1) shall be as prescribed in the same notice.\n(3) The Consumer Court shall consist of the Chairperson and Members as\nfollows:\n(a) District Judge of the concerned district\ndesignated by the Government of Nepal -Chairperson\n(b) Gazetted second class officer of Nepal Judicial\nService designated by the Government of Nepal -Member\n(c) Gazetted second class officer of the Government\nof Nepal designated by the Government of Nepal -Member\n28\n(4) The Government of Nepal shall notify the designation of the\nChairperson or Members pursuant to sub-section (3) in the Nepal Gazette.\n(5) The Government of Nepal shall consult the Judicial Council before the\nDistrict Judge is designated as the Chairperson of the Court, and of the Judicial\nService Commission before the officer of the Nepal Judicial Service is designated\nas a Member pursuant to sub-section (3).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "42", "title": "Application of jurisdiction of Court: (1) All the members shall collectively", "content": "exercise the jurisdiction of the Court.\nProvided that the Bench in which at least one Member is present may carry\nout procedural matters other than detention, and the Bench in which two Members\nare present may take all other matters including detention.\n(2) If unanimity is not reached while trying and settling a case in presence\nof two Members, the case shall be settled as per the opinion of the Chairperson if\nit is the Bench including the Chairperson in case it is the procedural matter of the\ncase.\n(3) If it is the Bench in which the Chairperson is not present, it shall be as\nper the opinion of the senior member based on the appointment. If it is the decision\nor final order of the case, it shall be submitted to the Chairperson, and the opinion\nsupported by him or her shall be deemed to be the decision of the Court.\n(4) The three Members shall collectively exercise the jurisdiction of the\nBench and majority opinion including that of the Chairperson shall be deemed to\nbe the decision of the Court.\n(5) If all three Members have divergent opinion, the opinion of the\nChairperson prevails on the procedural matters and if it is on decision or final\norder it shall be forwarded to the concerned High Court for the decision, by\nspecifying the reasons for not being able to issue a decision or final order.\n(6) Hearing of the case pursuant to sub-section (5) shall be held in the single\nBench of the High Court and the decision or final order made by such a Bench\nshall be deemed to be the decision or final order of the Court.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "43", "title": "Contempt of Court: (1) The Court may initiate proceedings against the contempt", "content": "of court and if the act of contempt of court is found to be proved, the Court may\npunish the offender with a fine not exceeding ten thousand rupees or an\nimprisonment for a term not exceeding one year or with both.\n(2) Notwithstanding anything contained in sub-section (1), if the person\naccused of contempt of court apologizes to the satisfaction of the Court, the Court\n29\nmay not initiate the proceedings or excuse, reduce or change in punishment if the\npunishment has already been determined or issue an order with effect of non-\nexecution of the sentence, if the conditions are complied with by the accused.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "44", "title": "To make files or documents available: (1) If the Court or the Director General", "content": "of the Department orders any person, institution or office to submit or forward any\nfile, deed, document or any other proof as evidence in the course of the\nproceedings of the case, such a person, institution or office shall have to submit or\nforward such a file, deed, document or evidence, within the deadline determined\nby the Court or the Director General of the Department.\n(2) If it is obstructed to try, hear or settle the case, or if harassment or harm\nor injury is caused to any party due to the reason that any person, institution or\noffice has not complied with the order pursuant to sub-section (1), the Court or\nDirector General of the Department may impose upon such a person or institution\nor chief of office a fine not exceeding one thousand rupees each time.\n(3) Notwithstanding anything contained in sub-section (2), if such a person\nor institution or chief of office makes an application to the Court or the Director\nGeneral of the Department, within the time-limit determined by the Court or the\nDirector General, specifying the reason for not being able to abide by such order,\nstating that fine should not be imposed, and if the statement of such application is\nfound to be reasonable, the Court or the Director General of the Department may\nrevoke such an order for imposition of the fine.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "45", "title": "Appeal: An appeal may be made to the concerned High Court within thirty days", "content": "against the decision made by the Court under this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "46", "title": "Execution of decisions: If it is specified in the decision or order that the decision", "content": "or order is to be executed by any particular agency or official, the same agency or\nofficial shall execute the decision or final order made by the Court under this Act,\nand if it is not specified as such, it shall be executed by the concerned District\nCourt.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "47", "title": "Dissolution of the Court: (1) The Government of Nepal may dissolve the Court", "content": "at any time by a notification in the Nepal Gazette.\n(2) If the Court is dissolved pursuant to sub-section (1), the cases,\ncomplaints or petitions remained pending at the time of dissolution after being\nfiled in such Court shall be ipso facto transferred to the concerned District Court\nhaving territorial jurisdiction.\n30", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "48", "title": "Special provision relating to action and finalization of case: Notwithstanding", "content": "anything contained in Section 41, the concerned District Court shall have the\nauthority to take action, hear or try the case under this Act until the Court is\nconstituted pursuant to this Section.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "49", "title": "To table notice: The Government of Nepal shall have to table the notice published", "content": "pursuant to sub-section (1) of Section 41 or sub-section (1) of Section 47 in the\nHouse of Representatives.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-10", "title": "Chapter-10", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "50", "title": "Compensation may be claimed: If bodily, mental, financial, physical or other", "content": "kind of harm and injury is caused to any consumer by use of the goods or services\nsold or distributed contrary to this Act, or damage is occurred as a result of\ndefective production of goods, the consumer himself or herself, or any consumer\nassociation on his or her behalf, or the heir of the consumer if the consumer is\nincompetent or has already died, may make a complaint to the Court for\ncompensation from the person who has produced, imported, hoarded, transported,\nsold and distributed or provided such goods or services within six months from\nthe date of harm and injury caused.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "51", "title": "To provide compensation: If the consumer is wounded by the use of the goods", "content": "or services sold, distributed or provided contrary to this Act, treatment expenses,\ninterim relief amount for the daily subsistence as per the family circumstances\nthroughout the treatment period and, if it is proved, in course of the investigation,\nthat the consumer has suffered, the consumer, or the heir as per law, if he or she\nhas died, shall entitled to get the amount of compensation from the concerned\nproducer, importer, hoarder, carrier, distributor or seller concerned on the basis of\nsuch harm and injury.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "52", "title": "To determine the standards of compensation: (1) The Court shall, while", "content": "determining the amount to be received by the consumer for compensation pursuant\nto Section 51, have to determine it by taking following matters into consideration:\n(a) physical or mental suffering or pain caused to the victim, and\nits severity,\n(b) estimated expenses to be made for treatment if curable\ndamage is caused,\n31\n(c) depreciation caused in the capacity of the victim to generate\nincome due to the physical or mental damage,\n(d) victim’s age and his or her family responsibility, if incurable\ntype of physical or mental damage is caused,\n(e) number of victim’s family members who are dependent upon\nhim or her and minimum expenses required for the\nmaintenance of their livelihood if the victim has died,\n(f) such other matters, out of the matters claimed by the victims,\nas found to be proper and appropriate,\n(g) financial and business condition of the producer, importer,\nhoarder, seller and service provider.\n(2) Other provisions relating to the determination of compensation pursuant\nto sub-section (1) shall be as prescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-11", "title": "Chapter-11", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "53", "title": "To provide essential goods or services at fair price: The Government of Nepal", "content": "may make provision to provide the essential foods or other goods or services\ndetermined pursuant to Section 19 at a fair price as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "54", "title": "To extend support: (1) If the Department seeks support of local administration", "content": "and police in the course of implementing this Act, it shall be the duty of the local\nadministration and the police to extend such support.\n(2) In the course of carrying out inquiry, monitoring or inspection under\nthis Act, it shall be the duty of all the concerned to extend necessary support to\nthe official carrying out such inquiry, monitoring or inspection or to the person,\nteam or Inspection Officer deputed under this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "55", "title": "Liability of institution: (1) If any business institution commits any act considered", "content": "as offence under this Act, the official who works in the capacity of the chief\nadministrative official of such an institution shall have the responsibility and\nliability of such act.\n(2) Notwithstanding anything contained in sub-section (1), such a person\nshall not have to bear the liability regarding the offence occurred before he or she\nbecame the chief administrative official.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "56", "title": "Reward to informant: (1) After eventually settling the case filed upon being", "content": "investigated as per the information provided by the person who provides\n32\ninformation that the offence has been or is going to be committed, such a person\nshall be rewarded with the ten percent of the claimed amount recovered or one\nmillion rupees, whichever is the lesser.\n(2) Notwithstanding anything contained in sub-section (1), no employee of\nthe Government of Nepal or corporate institution or the family member or\nrepresentative of the consumers’ organization or institution or employee deputed\nfor monitoring or their family member shall be entitled to the reward referred to\nin this Section.\n(3) The name, address of the informant pursuant to this Section and the\ndetails of the information received from him or her shall be kept confidential.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "57", "title": "No to bar to prosecute case under prevailing law: If any act which is deemed", "content": "as an offence under this Act is also deemed as an offence under other prevailing\nlaw, this Act shall not bar to prosecute the case under such law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "58", "title": "Government of Nepal to be plaintiff: The Government of Nepal shall be the", "content": "plaintiff in the cases under this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "59", "title": "Investigation and filing of case: (1) The Inspection Officer shall carry out", "content": "investigation of the case relating to the offence under this Act.\n(2) The Inspection Officer shall, after completing the investigation, have to\nforward the matter to the concerned government attorney for the decision on\nwhether or not to institute the case, and if decision is made by the government\nattorney to institute the case, the Inspection Officer shall file the case.\n(3) While filing the case pursuant to sub-section (1), the Inspection Officer\nshall file the case before the Director General of the Department in connection\nwith the case relating to the offence carrying the punishment referred to in sub-\nsection (1) of Section 40, and before the Court if the Court has been constituted\nand before the District Court concerned if the Court has not been constituted in\nconnection with the case carrying punishment referred to in sub-section (3) of\nSection 40.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "60", "title": "To follow summary procedures: (1) While trying and settling the cases filed", "content": "under this Act, procedures shall have to be followed pursuant to the Summary\nProcedures Act, 2028 (1972).\n(2) Notwithstanding anything contained in sub-section (1), general\nprocedures shall have to be followed in the cases carrying the sentence of\nimprisonment for more than three years.\n33", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "61", "title": "Saving of act done in good faith: The Consumer Protection Council, Central", "content": "Monitoring Committee, Local Market Monitoring Committee, Inspection Officer\nor any employee of the Government of Nepal, Provincial Government or Local\nLevel shall not be personally responsible for any act done by him or her in good\nfaith while performing his or her duties under this Act or the rules framed under\nthis Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "62", "title": "To be in accordance with this Act: The matters contained in this Act shall be in", "content": "accordance with this Act and other matters shall be in accordance with the\nprevailing law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "63", "title": "Power to frame rules: (1) The Government of Nepal may frame necessary rules", "content": "in order to implement this Act.\n(2) The Provincial Government may frame necessary rules in order to make\nthe activities relating to market monitoring systematic and effective pursuant to\nSection 27.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "64", "title": "Power to frame and enforce directives, procedures or standards: (1) The", "content": "Ministry may, in order to implement this Act and the rules framed by the\nGovernment of Nepal under this Act, frame and enforce directives, procedures or\nstandards as necessary.\n(2) The concerned Rural Municipality or Municipality may, in order to\nmake the activities relating to market monitoring systematic and effective pursuant\nto Section 28, frame and enforce necessary directives and procedures.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "65", "title": "Repeal and Saving: (1) The Consumer Protection Act, 2054 (1998) is hereby", "content": "repealed.\n(2) The acts and actions performed under the Act pursuant to sub-section\n(1) shall be deemed to have been performed under this Act.\n34", "children": []}]}]$CODExb5b2a3640d$::jsonb,$CODExc95378ef4d$consumer protection act.pdf$CODExc95378ef4d$) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, original_title=EXCLUDED.original_title, document_type=EXCLUDED.document_type, year_bs=EXCLUDED.year_bs, year_ad=EXCLUDED.year_ad, total_pages=EXCLUDED.total_pages, nodes=EXCLUDED.nodes, source_filename=EXCLUDED.source_filename;
